// Build a buffer entry from a Messenger location attachment (older clients) or a shared map link
const md = $('Message Data').item.json;
const req = $('Webhook').item.json;
const msg = ((req.body || req).entry?.[0]?.messaging?.[0]?.message) || {};
const att = (msg.attachments || [])[0] || {};
const p = att.payload || {};
const c = p.coordinates || {};
const lat = c.lat ?? c.latitude ?? null;
const lng = c.long ?? c.lng ?? c.longitude ?? null;
const label = att.title || p.title || '';

let text = '[موقع مرسل]';
if (label) text += ' ' + label;
if (lat != null && lng != null) {
  text += ' | الإحداثيات: ' + lat + ', ' + lng + ' | الخريطة: https://maps.google.com/?q=' + lat + ',' + lng;
} else if (att.url || p.url) {
  text += ' | الرابط: ' + (att.url || p.url);
}

return {
  json: {
    phone: md.phone,
    wamid: md.wamid,
    msgType: 'location',
    processedText: text,
    mediaId: '',
    phoneNumberId: md.phoneNumberId,
    debounceToken: md.debounceToken,
    latitude: lat,
    longitude: lng,
  },
};

// Build a buffer entry for Messenger message types without a dedicated branch (sticker, video, file, shared link...)
const md = $('Message Data').item.json;
const req = $('Webhook').item.json;
const msg = ((req.body || req).entry?.[0]?.messaging?.[0]?.message) || {};
const att = (msg.attachments || [])[0] || {};
const p = att.payload || {};
const type = md.msgType || att.type || 'unknown';
// Messenger's built-in thumbs-up (like) stickers
const LIKE_STICKERS = ['369239263222822', '369239343222814', '369239383222810'];

let text;
switch (type) {
  case 'sticker':
    text = LIKE_STICKERS.includes(String(p.sticker_id)) ? '(ستيكر 👍)' : '(ستيكر)';
    break;
  case 'video':
    text = '[فيديو مرسل]';
    break;
  case 'file':
    text = '[ملف مرسل]';
    break;
  case 'fallback': {
    const url = att.url || p.url || '';
    text = '[رابط مرسل' + (url ? ': ' + url : '') + ']';
    break;
  }
  default:
    text = '[رسالة من نوع غير مدعوم: ' + type + ']';
}

const caption = String(msg.text || '').trim();
if (caption) text += ' ' + caption;

return {
  json: {
    phone: md.phone,
    wamid: md.wamid,
    msgType: type,
    processedText: text,
    mediaId: '',
    phoneNumberId: md.phoneNumberId,
    debounceToken: md.debounceToken,
  },
};

// Safety net for the agent reply: remove echoed internal data, fix common non-Iraqi wording,
// never ask to confirm an order while the contact phone is missing,
// and never claim a confirmed order that was not created.
// STAGE / NOTIFICATION_TYPE lines are kept here; Parse Agent Output strips them.
const customerId = String($('Build User Prompt').item.json.phone || '');
const userPrompt = String($('Build User Prompt').item.json.userPrompt || '');
const raw = String($json.output ?? $json.text ?? '');
let text = raw;

// Echoed parts of the internal data block (labels, ids, cart JSON, hints)
const LEAKS = [
  /\[?بيانات داخلية[^\]\n]*\]?/g,
  /(?:معرّ?ف الزبون(?:\s*بماسنجر)?|customer[_\s-]?id|PSID)\s*[:：]?\s*\d*/gi,
  /(?:بيانات الجلسة الحالية|السلة الحالية)\s*[:：]\s*(?:\{[^\n]*\})?/g,
  /رسائل (?:العميل|الزبون)\s*[:：]/g,
  /\[?رقم هاتف كتبه الزبون[^\]\n]*\]?/g,
  /\[(?:تنبيه|تذكير داخلي)[^\]\n]*\]?/g,
];
for (const re of LEAKS) text = text.replace(re, '');

// Never send the Messenger id, even inside a sentence
if (customerId.length >= 6) text = text.split(customerId).join('');

// English size names and common MSA / misspelling slips -> Iraqi wording
// (a reply that already addresses a woman, with چ, gets «رايدة» instead of «رايد»)
const femWording = /چ/.test(text);
const FIXES = [
  [/\bX\s*[-‑–]?\s*Large\b/gi, 'اكس لارج'],
  [/\bXL\b/g, 'اكس لارج'],
  [/\bLarge\b/gi, 'لارج'],
  [/\bMedium\b/gi, 'ميديم'],
  [/\bSmall\b/gi, 'سمول'],
  [/(^|[^ء-ي])حسن(?:اً|ًا|ا)(?![ء-ي])[ \t]*[،,]?[ \t]*/g, '$1تمام، '],
  // Count questions take «شكم» and «رايد/رايدة» (never «شكد قطعة» or «تريد»); price and amount questions take «شكد»
  [/(^|[^ء-ي])كم\s+(?:عدد\s+القطع|قطع[ةه]?)(?:\s+(?:التي|الي|اللي))?(?:\s+تريد(ين)?(?:ها)?)?\s*[؟?]/g,
    (m, pre, f) => pre + 'شكم قطعة ' + (f || femWording ? 'رايدة' : 'رايد') + '؟'],
  [/(^|[^ء-ي])(?:كم|شكد)(?=\s+(?:عدد|قطع|قطع[ةه]|حب[ةه]|حبات|تي?شي?رت(?:ات)?|لون|[أا]لوان)(?![ء-ي]))/g, '$1شكم'],
  [/(^|[^ء-ي])شكم(\s+(?:قطع|قطع[ةه]|حب[ةه]|حبات|تي?شي?رت(?:ات)?|لون|[أا]لوان))\s+تريد(ين)?(?![ء-ي])/g,
    (m, pre, noun, f) => pre + 'شكم' + noun + ' ' + (f || femWording ? 'رايدة' : 'رايد')],
  [/(^|[^ء-ي])كم(?=\s)/g, '$1شكد'],
  [/تشيارت|تيشارت|تي شيرت/g, 'تيشيرت'],
  [/عندك(\s+)(تيشيرت|تشيرت)/g, 'عدنا$1$2'],
  [/لدينا/g, 'عدنا'],
  [/لا يوجد/g, 'ماكو'],
  [/(^|[^ء-ي])يوجد(?![ء-ي])/g, '$1اكو'],
  [/(^|[^ء-ي])الآن(?![ء-ي])/g, '$1هسة'],
  [/(^|[^ء-ي])اللي(?![ء-ي])/g, '$1الي'],
  [/(^|[^ء-ي])هل\s+/g, '$1'],
];
for (const [re, rep] of FIXES) text = text.replace(re, rep);

// One word for "can": أقدر/نقدر/تقدر/يقدر -> أكدر/نكدر/تكدر/يكدر, but only in the "can" sense
// (after ما/لا, or followed by a verb of the same person). "نقدّر تفهمك" and "أقدّم" stay untouched.
const SAME_PERSON = { 'أ': 'أإاآ', 'إ': 'أإاآ', 'ا': 'أإاآ', 'آ': 'أإاآ', 'ن': 'ن', 'ت': 'ت', 'ي': 'ي' };
text = text.replace(
  /(^|[^\p{L}])((?:و?(?:ما|لا))\s+)?([أإاآنتي])قدر(ين|ون|وا)?(?![\p{L}\p{M}])(?=(\s+\p{L})?)/gu,
  (m, pre, neg, p, suf, next) => {
    const nextLetter = next ? next.trim()[0] : '';
    if (!neg && !(nextLetter && SAME_PERSON[p].includes(nextLetter))) return m;
    return pre + (neg || '') + ('إاآ'.includes(p) ? 'أ' : p) + 'كدر' + (suf || '');
  },
);

// Messenger shows markdown literally
text = text.replace(/\*\*|__/g, '').replace(/^[ \t]*#{1,6}[ \t]*/gm, '');

// Never claim the order is confirmed while the same reply is still collecting it
// (create_order did not run in this turn). Post-sale answers about real orders are left alone.
const ran = (node) => { try { return $(node).isExecuted === true; } catch (e) { return false; } };
const bare = (s) => String(s).replace(/\p{M}/gu, '');
const STILL_ORDERING = /معلومات التوصيل|الاسم الثلاثي|أقرب نقطة دالة|للسلة|بالسلة|تضيف(?:ه|يه)|عنوان[كچ] الكامل|[أا]ثبتل[كچج] الطلب/;
const CLAIM = /ثبتت|ثبتنا|تم تثبيت|تم الطلب|انحجز|(?:طلبك|طلبچ|طلبيتك|طلبيتچ|الطلب)\s+(?:تثبت|مثبت)/;
if (!ran('create_order') && STILL_ORDERING.test(bare(text))) {
  text = text
    .split('\n')
    .map((line) => line
      .split(/(?<=[.!؟?])/)
      .map((s) => (CLAIM.test(bare(s)) && !/[؟?]/.test(s) ? ' سجّلت اختيارك ✅ ' : s))
      .join(''))
    .join('\n');
}

// Internal words never reach the customer: no "add to cart" talk, the cart is "طلبك", and a read-back asks «تمام هيج؟»
const femReply = /چ/.test(text);
const INTERNAL = [
  [/[ \t]*[،,]?[ \t]*و?ضيف(?:لي|لنا|ه|ها|هم)?[ \t]+(?:لل|بال|ال)سل[ةه](?![ء-ي])/g, ''],
  [/(^|[^ء-ي])(?:صحيح|صح)[ \t]+(?:هالشي|هذا الشي|هالمعلومات|هذا)[ \t]*[؟?]/g, '$1تمام هيج؟'],
  [/(^|[^ء-ي])و?(?:إذا|اذا|لو)[ \t]+(?:كان[ \t]+)?(?:صحيح|صح)[ \t]*[،,][ \t]*/g, '$1'],
  [/(^|[^ء-ي])و?خليني[ \t]+[أاآ]خذ[ \t]+معلومات[ \t]+التوصيل(?=[ \t]*(?:[.!،,\n]|$))/g,
    '$1' + (femReply ? 'وياريت تدزيلي عنوانچ الكامل ورقم التليفون علمود نأكد الحجز' : 'وياريت تدزلي عنوانك الكامل ورقم التليفون علمود نأكد الحجز')],
  [/للسل[ةه](?![ء-ي])/g, femReply ? 'لطلبچ' : 'لطلبك'],
  [/بالسل[ةه](?![ء-ي])/g, femReply ? 'بطلبچ' : 'بطلبك'],
  [/(^|[^ء-ي])السل[ةه](?![ء-ي])/g, '$1الطلب'],
];
for (const [re, rep] of INTERNAL) text = text.replace(re, rep);

// Phone gate. Iraqi mobile = 07XX XXX XXXX (also +964 / 00964 / no leading 0, Arabic digits allowed)
const toLatin = (s) => String(s)
  .replace(/[٠-٩]/g, (d) => '٠١٢٣٤٥٦٧٨٩'.indexOf(d))
  .replace(/[۰-۹]/g, (d) => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
const PHONE_RE = /(?:^|\D)((?:(?:\+|00)[ \t]?964[ \t\-.()]{0,2}|0)?7\d{2}[ \t\-.()]{0,2}\d{3}[ \t\-.()]{0,2}\d{4})(?!\d)/;
const PHONE_WORD = /رقم (?:ال)?(?:هاتف|موبايل|تلفون)/;
const CONFIRM_Q = /[أا]ثب\p{M}*ت\p{M}*(?:\s?(?:لك|لچ|لج))?\s+(?:الطلب|طلبك|طلبچ)\s*[؟?]/u;
const stageOf = (s) => Number((String(s).match(/STAGE:\s*(\d+)/i) || [])[1] ?? -1);

// The model usually leaves out the hidden STAGE line (and NOTIFICATION_TYPE: order_completed after an order).
// Fill in what is missing from what actually happened in this turn, so the rules below, Polish Reply Style and
// Parse Agent Output see a stage either way. Lines the model did write are kept as they are.
const hints = (() => { try { return $('Conversation Hints').first().json || {}; } catch (e) { return {}; } })();
const isNewConversation = hints.isNewConversation === true;
const orderConfirmed = ran('create_order') && /رقم\s*(?:الطلب\s*)?[#:]?\s*[0-9٠-٩]+/.test(bare(text));
let stageInferred = false;
if (stageOf(text) < 0) {
  const t = bare(text);
  let inferred = 0; // greeting or small talk
  if (orderConfirmed) inferred = 4; // order created in this turn
  else if (/NOTIFICATION_TYPE:\s*complaint/i.test(text) || /تحو[ّ]?ل لموظف|يتابع وياك/.test(t)) inferred = 5; // complaint or handoff
  else if (CONFIRM_Q.test(text)) inferred = 3; // summary waiting for confirmation
  else if (ran('update_session_data') || /طلب[كچ] هسة صار|تمام هيج[؟?]/.test(t)) inferred = 2; // items chosen
  else if (/معلومات التوصيل|الاسم الثلاثي|أقرب نقطة دالة|عنوان[كچ] الكامل|بيا محافظة/.test(t)) inferred = 3; // delivery details
  else if (ran('get_available_products') || ran('find_delivery_area') || /متوفر|ماكو|عدنا|سعر|دينار|قياس|التوصيل/.test(t)) inferred = 1; // inquiry
  const meta = text.match(/NOTIFICATION_TYPE:[^\n]*/i);
  text = text.replace(/\n?[ \t]*NOTIFICATION_TYPE:[^\n]*/gi, '').replace(/\s*$/, '') + '\nSTAGE: ' + inferred + (meta ? '\n' + meta[0].trim() : '');
  stageInferred = true;
}
if (orderConfirmed && !/NOTIFICATION_TYPE:/i.test(text)) text = text.replace(/\s*$/, '') + '\nNOTIFICATION_TYPE: order_completed';

if (stageOf(text) !== 4 && !/order_completed/i.test(text) && CONFIRM_Q.test(text) && !PHONE_RE.test(toLatin(text))) {
  const given = (userPrompt.match(/contact_phone\)\s*:\s*(0\d{10})/) || [])[1];
  const fem = /چ/.test(text);
  const lines = text.split('\n');
  const qi = lines.findIndex((l) => CONFIRM_Q.test(l));
  const pi = lines.findIndex((l) => PHONE_WORD.test(l));
  if (given) {
    // The customer sent the number in this turn but the model left it out of the summary
    if (pi >= 0) {
      lines[pi] = /[:：]/.test(lines[pi]) ? lines[pi].replace(/[:：].*$/, ': ' + given) : '- رقم الهاتف: ' + given;
    } else {
      let at = qi;
      while (at > 0 && !lines[at - 1].trim()) at--;
      lines.splice(at, 0, '- رقم الهاتف: ' + given);
    }
    text = lines.join('\n');
  } else {
    // Replace the whole question line so no half sentence is left behind
    const wrongNumber = pi >= 0 && /\d{3,}/.test(toLatin(lines[pi]));
    lines[qi] = wrongNumber
      ? 'رقم الهاتف الي وصلني مو كامل أو غلط؛ رقم الموبايل لازم يكون 11 رقم ويبدي بـ 07. ' + (fem ? 'اكتبيه' : 'اكتبه') + ' مرة ثانية حتى أثبّت الطلب.'
      : 'بس ناقص رقم الهاتف، وهو ضروري حتى يتصل ' + (fem ? 'بيچ' : 'بيك') + ' المندوب. ' + (fem ? 'اكتبي رقم موبايلچ' : 'اكتب رقم موبايلك') + ' (يبدي بـ 07) حتى أثبّت الطلب.';
    text = lines.join('\n').replace(/STAGE:\s*\d+/i, 'STAGE: 3');
  }
}

// Emoji: at most one besides 🌷. 🌷 stays on the first reply of a conversation and on a confirmed order;
// Polish Reply Style then puts it in its final place (after the greeting, or alone at the end of the confirmation).
const stage = stageOf(text);
if (stage !== 4 && !isNewConversation) text = text.replace(/[ \t]*🌷/gu, '');
let emojiCount = 0;
text = text.replace(
  /[ \t]*\p{Extended_Pictographic}(?:\p{M}|\p{Emoji_Modifier}|\p{Join_Control}\p{Extended_Pictographic})*/gu,
  (e) => (e.includes('🌷') ? e : (++emojiCount > 1 ? '' : e)),
);

text = text
  .split('\n')
  .map((line) => line.replace(/[ \t]{2,}/g, ' ').replace(/[ \t]+([.،,؟?!])/g, '$1').trim())
  .join('\n')
  .replace(/^[\s:،,-]+/, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return { json: { ...$json, output: text, rawOutput: raw, stageInferred } };

// Hints for the agent: start of a conversation (greeting + rose), the governorate the customer gave (in these messages or
// earlier in the conversation), areas that exist in several governorates, areas missing from the (partial) directory, and
// area names that are probably a misheard / misspelled directory name (voice transcription: العمرية → العامرية)
const base = $('Build User Prompt').first().json;
const session = (() => { try { return $('Re-read Customer Session').first().json || {}; } catch (e) { return {}; } })();
// Customer messages from the last 24 hours, newest first. The current batch is logged after the reply, so it is not in here.
const history = (() => {
  try { return $('Load Recent Customer Messages').all().map((i) => i.json).filter((r) => r && r.message_text); } catch (e) { return []; }
})();

// A conversation starts when the bot has not replied to this customer in the last 24 hours
const lastReply = session.last_reply_at ? new Date(session.last_reply_at).getTime() : 0;
const isNewConversation = !lastReply || Date.now() - lastReply > 24 * 60 * 60 * 1000;

// Same mapping as public.ar_normalize() in Supabase (delivery_areas.area_name_norm): ة/ه، ى/ي، أ/إ/آ/ا، ؤ، ئ، گ، چ، no diacritics
// Marks dropped: Arabic diacritics 0x64B-0x65F and 0x670, tatweel 0x640, invisible direction marks 0x200B-0x200F and 0x61C
const isMark = (c) => { const o = c.charCodeAt(0); return (o >= 0x64B && o <= 0x65F) || o === 0x670 || o === 0x640 || (o >= 0x200B && o <= 0x200F) || o === 0x61C; };
const stripMarks = (s) => Array.from(String(s || '')).filter((c) => !isMark(c)).join('');
const norm = (s) => stripMarks(s)
  .replace(/[أإآٱ]/g, 'ا').replace(/[ىیئ]/g, 'ي').replace(/[ۀةۃەھ]/g, 'ه')
  .replace(/ؤ/g, 'و').replace(/ک/g, 'ك').replace(/گ/g, 'ق').replace(/ڤ/g, 'ف')
  .replace(/پ/g, 'ب').replace(/چ/g, 'ج').replace(/ء/g, '')
  .replace(/\s+/g, ' ').trim();
const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
// Area names that are also everyday words (بفضل الله، مع العلم، الشبكة ضعيفة، الحر هواية): only written with their ال
// after a place cue (بالفضل، منطقة النصر، بغداد الرشيد), or an ال name sent alone as the whole message (الصدر)
const WEAK = new Set(['الحي', 'النصر', 'الوحدة', 'الوفاء', 'الإصلاح', 'الرشيد', 'المدينة', 'الثورة', 'الجمهورية', 'القبلة',
  'الرياض', 'الطليعة', 'الخيرات', 'البشائر', 'الميدان', 'الصدر', 'العلم', 'الشبكة', 'المشروع', 'الملتقى', 'الأحرار',
  'المشاهدة', 'البلديات', 'البنوك', 'المسبح', 'الكريمات', 'الفضل', 'الحر', 'بلد', 'الدور', 'حديثة', 'القائم', 'الدبس',
  'الخالص', 'تازة', 'حرير', 'نفر', 'فايدة', 'السنية', 'الشافعية', 'الصلاحية', 'طق طق'].map(norm));
// Area names that are also first names: with ال they are the place (المنصور، القاسم)، without it the person (منصور، قاسم)
const NAME_AL = new Set(['المنصور', 'القاسم', 'الحمزة', 'الزبير', 'الأمين', 'الخضر', 'الغدير', 'الزهور', 'الفضيلة',
  'الميمونة', 'المأمون', 'المعتصم'].map(norm));
// Area names that are also names or surnames as written (ربيعة، كنعان، احمد العبيدي): only after a place cue (ساكن بربيعة)
const NAME_CUE = new Set(['ربيعة', 'كنعان', 'شوان', 'ديانا', 'يثرب', 'رانية', 'سوران', 'ليلان', 'خبات', 'جومان', 'بارزان',
  'سيروان', 'الوليد', 'العبيدي', 'الرفاعي', 'السلمان', 'الإسحاقي', 'الطعمة', 'سليمان بك', 'تاج الدين', 'عز الدين سليم',
  'علي الشرقي', 'سيد صادق'].map(norm));
const PRE = '(^|[^ء-ي])';
const END = '(?![ء-ي])';
const ATTACHED = '(?:[وبلف]|وب|بال|وال|لل)?';
const WITH_AL = '(?:(?:[وبلفك]|وب)?ال|و?لل)';
// A place cue: بـ attached, a place word, or a governorate / city name just before (بغداد الرشيد). Governorate words
// come from the table further down, before the first pattern is built.
let GOV_CUE = '';
const cueBefore = () => '(?:و?ب|(?:و?(?:في|من|حي|منطقه|المنطقه|ناحيه|قضا|مدينه|ساكن|ساكنه|سكنه|عنواني|العنوان)'
  + (GOV_CUE ? '|' + GOV_CUE : '') + ')\\s+[وبلف]?)';
// Whole word, allowing attached prepositions (ب، و، ل، ف) and an optional ال. «حي X» names need «حي» or a place cue
// before X; everyday words and names follow the rules of their lists above.
const patterns = new Map();
const patternOf = (name) => {
  let p = patterns.get(name);
  if (p) return p;
  const n = norm(name);
  const isHay = n.startsWith('حي ');
  const kind = WEAK.has(n) ? 'weak' : NAME_AL.has(n) ? 'nameAl' : NAME_CUE.has(n) ? 'nameCue' : '';
  const hasAl = !isHay && n.startsWith('ال');
  const bare = escapeRe((isHay ? n.slice(3) : n).replace(/^ال/, ''));
  const open = '(?:ال)?' + bare;
  const cue = cueBefore();
  // With a cue, an ال name keeps its ال (بالفضل، لا بفضل الله); «لل» already holds it (للرشيد)
  // …or with an address word right after it (الصدر قطاع ١٠، الرشيد قرب السيطرة)
  const cued = (core) => {
    const lead = core.startsWith('ال') ? WITH_AL + bare : ATTACHED + core;
    return new RegExp(PRE + '(?:(?:' + cue + core + '|و?لل' + bare + ')' + END + '|' + lead + '\\s+(?:قطاع|محله|زقاق|شارع|قرب|جنب|مقابل)' + END + ')');
  };
  if (isHay) p = { kind: 'hay', strong: new RegExp(PRE + ATTACHED + 'حي\\s+(?:ال)?' + bare + END), cued: cued(open) };
  else if (kind === 'nameAl') p = { kind, strong: new RegExp(PRE + WITH_AL + bare + END) };
  else if (kind) p = { kind, cued: cued(hasAl ? 'ال' + bare : bare), alone: hasAl ? new RegExp('^\\s*(?:[وب]?ال|لل)' + bare + '[\\s.!؟?،]*$') : null };
  else p = { kind, strong: new RegExp(PRE + ATTACHED + open + END) };
  patterns.set(name, p);
  return p;
};
