      : (a.governorates.length > 1 ? 'تقصد ' + a.area + '؟ ' + a.area + ' اكو ب' + a.governorates.join(' وب') + '، يا وحدة؟' : 'تقصد ' + a.area + ' ب' + a.governorates[0] + '؟');
    hint += ' اكتب الاسم الصحيح ' + q(a.area) + ' بردك وبالملخص، وتأكد منه بسؤال قصير ضمن ردك، مثل: «' + ask + '»]';
  } else {
    hint += ' اسأله بسؤال قصير يا وحدة يقصد وسمِّ الأسماء الصحيحة من الدليل' + (govFrom ? '' : '، وإذا المحافظة مو معروفة اسأله عنها بنفس السؤال') + '.]';
  }
}
if (earlierCorrections.length) {
  hint += '\n\n[تنبيه: تصحيح أسماء مناطق من رسائل الزبون السابقة (من دليل المناطق): '
    + earlierCorrections.map((s) => q(s.heard) + ' هي ' + q(s.suggestions[0].area) + ' (' + govText(s.suggestions[0]) + ')').join('، و')
    + '. إذا تكتب العنوان أو الملخص اكتب الاسم الصحيح من الدليل، مو الاسم الغلط.]';
}
if (unknownAreas.length) {
  hint += '\n\n[تنبيه: ' + unknownAreas.map(q).join(' و')
    + ' مو بدليل المناطق، وهذا عادي: الدليل مو كامل ونوصل لكل مناطق العراق. ممنوع تقول «ما حصلت معلومات» أو «ما لكيت المنطقة»، وممنوع تذكر محافظات لها من عندك'
    + (govFrom ? '. المحافظة معروفة، اعتمدها وكمّل.]' : '. إذا المحافظة مو معروفة من المحادثة، اسأله عنها بس.]');
}

return [{ json: { ...base, userPrompt: base.userPrompt + hint, isNewConversation, ambiguousAreas, unknownAreas, govsSaid, govsBefore, areaSuggestions, earlierCorrections }, pairedItem: { item: 0 } }];

// Style pass after Clean Agent Reply: Iraqi wording (شكم / رايد / عدنا), greeting + 🌷 only at the start of a conversation,
// 🌷 alone on the order confirmation, and no summary confirmation without an explicit governorate.
const hints = (() => { try { return $('Conversation Hints').first().json || {}; } catch (e) { return {}; } })();
const ran = (node) => { try { return $(node).isExecuted === true; } catch (e) { return false; } };
const bare = (s) => String(s).replace(/\p{M}/gu, '');
const stageOf = (s) => Number((String(s).match(/STAGE:\s*(\d+)/i) || [])[1] ?? -1);
let text = String($json.output ?? '');

// Internal hint tags never reach the customer
text = text.replace(/\[(?:بداية محادثة|محادثة مستمرة|تنبيه: منطقة)[^\]\n]*\]?/g, '');

const FIXES = [
  [/(^|[^ء-ي])(?:كم|شكد)(\s+(?:قطعة|قطعه|قطع|حبة|حبات|تيشيرت|تيشيرتات|تشيرت|واحد|وحدة|لون|قياس))/g, '$1شكم$2'],
  [/(^|[^ء-ي])عندنا(?![ء-ي])/g, '$1عدنا'],
  [/(^|[^ء-ي])تريدين(?![ء-ي])/g, '$1رايدة'],
  [/(^|[^ء-ي])تريد(ها|ه)?(?![ء-ي])/g, '$1رايد$2'],
  [/شنو\s+تحتاج/g, 'شنو رايد'],
  [/(شكم\s+\S+\s+رايد[ةه]?)\s+(?:اختيارها|تختارها|تاخذها|تطلبها|تطلب|تاخذ)(?=\s*[؟?])/g, '$1'],
  [/(^|[^ء-ي])إليك(?![ء-ي])[ \t]*/g, '$1هاي '],
  [/(^|[^ء-ي])ممكن\s+(أحوّلك|أحولك|احولك)/g, '$1أكدر $2'],
];
for (const [re, rep] of FIXES) text = text.replace(re, rep);

// Governorate gate: never ask to confirm a summary without an explicit Iraqi governorate
const CONFIRM_Q = /[أا]ثب\p{M}*ت\p{M}*(?:\s?(?:لك|لچ|لج))?\s+(?:الطلب|طلبك|طلبچ)\s*[؟?]/u;
if (CONFIRM_Q.test(text) && !ran('create_order')) {
  const normAr = (s) => bare(s).replace(/[أإآ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه');
  const GOVS = ['بغداد', 'البصرة', 'نينوى', 'الموصل', 'أربيل', 'هولير', 'السليمانية', 'دهوك', 'كركوك', 'ديالى', 'بعقوبة',
    'الأنبار', 'الرمادي', 'الفلوجة', 'صلاح الدين', 'تكريت', 'سامراء', 'بابل', 'الحلة', 'كربلاء', 'النجف', 'واسط', 'الكوت',
    'القادسية', 'الديوانية', 'المثنى', 'السماوة', 'ذي قار', 'الناصرية', 'ميسان', 'العمارة', 'حلبجة'].map(normAr);
  const plain = normAr(text).replace(/ستايل بغداد/g, '');
  if (!GOVS.some((g) => plain.includes(g))) {
    const fem = /چ/.test(text);
    text = text
      .split('\n')
      .map((l) => (CONFIRM_Q.test(l) ? 'بس حتى أثبّت العنوان صح، ' + (fem ? 'كوليلي' : 'كلي') + ' بيا محافظة؟' : l))
      .join('\n')
      .replace(/STAGE:\s*\d+/i, 'STAGE: 3');
  }
}

// Greeting + 🌷 only on the first reply of a conversation; ongoing conversations drop the greeting (keep "وعليكم السلام" when the customer said salam)
const isNew = hints.isNewConversation === true;
const orderDone = ran('create_order') && (stageOf(text) === 4 || /order_completed/i.test(text));
const EMOJI_RE = /[ \t]*\p{Extended_Pictographic}(?:\p{M}|\p{Emoji_Modifier}|\p{Join_Control}\p{Extended_Pictographic})*/gu;
const GREET_RE = /^(?:(?:يا\s+)?هلا(?:\s+و(?:غلا|الله|سهلا|مرحبا))?|أهل[اًا]*(?:\s+و\s*سهل[اًا]*)?|اهل[اًا]*(?:\s+و\s*سهل[اًا]*)?|مرحب[اًا]*|مراحب|حيا[كچ](?:\s+الله)?|وعليكم\s+السلام(?:\s+ورحمة\s+الله(?:\s+وبركاته)?)?)(?![ء-ي])(?:\s+(?:بي[كچج]|بيكم|ب[كچ]|يا\s+هلا|نورتنا|نورتينا|وغلا|حيا[كچ]\s+الله))*[\s،,!.]*/u;
const isMeta = (l) => /^(?:STAGE|NOTIFICATION_TYPE)\s*:/i.test(l.trim());
const lines = text.split('\n');
const first = lines.findIndex((l) => l.trim());
if (first >= 0 && !isMeta(lines[first])) {
  const line = lines[first];
  const lineText = line.replace(EMOJI_RE, '').trim();
  const greets = GREET_RE.test(lineText);
  if (isNew && !orderDone) {
    if (!greets) lines.splice(first, 0, 'هلا وغلا 🌷');
    else if (!line.includes('🌷')) lines[first] = line.replace(/\s*$/, ' 🌷');
  } else if (!isNew && greets) {
    const salam = /^وعليكم/.test(lineText) && /سلام عليكم/.test(String(hints.combinedMessage || ''));
    if (!salam) {
      const rest = lineText.replace(GREET_RE, '').trim();
      const more = lines.slice(first + 1).some((l) => l.trim() && !isMeta(l));
      if (!rest || (more && rest.length < 50 && !/[؟?]/.test(rest))) lines.splice(first, 1);
      else lines[first] = rest;
    }
  }
}
text = lines.join('\n');

if (orderDone) {
  // Order confirmation: 🌷 alone at the end of the message
  const ls = text.replace(EMOJI_RE, '').split('\n');
  let last = ls.length - 1;
  while (last > 0 && (!ls[last].trim() || isMeta(ls[last]))) last--;
  ls[last] = ls[last].replace(/\s*$/, ' 🌷');
  text = ls.join('\n');
} else {
  let roseKept = false;
  let others = 0;
  text = text.replace(EMOJI_RE, (em) => {
    if (em.includes('🌷')) {
      if (isNew && !roseKept) { roseKept = true; return em; }
      return '';
    }
    return ++others > 1 ? '' : em;
  });
}

text = text
  .split('\n')
  .map((l) => l.replace(/[ \t]{2,}/g, ' ').replace(/[ \t]+([.،,؟?!])/g, '$1').trim())
  .join('\n')
  .replace(/^[\s:،,-]+/, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return { json: { ...$json, output: text } };

parameters.query:
SELECT (
  SELECT message_text FROM conversation_log
  WHERE phone_number = $1 AND direction = 'outgoing' AND message_text IS NOT NULL
    AND created_at > now() - interval '24 hours'
  ORDER BY created_at DESC LIMIT 1
) AS last_bot;

parameters.jsCode:
// The merged transcript plus the words the merging model was not sure of. If the merge call failed, the first engine
// that heard something is used as is; if every engine failed, Build Audio Entry reports a technical problem.
const cand = $('Prepare Reconcile').first().json;
if (cand.allFailed) return [{ json: { error: 'all speech-to-text engines failed' }, pairedItem: 0 }];
let ear = 'gpt-4o-transcribe + gpt-transcribe + whisper-large-v3 -> gpt-5.4-mini';
let text = '';
let unsure = [];
try {
  const o = JSON.parse($input.first().json.choices[0].message.content);
  text = String(o.text || '').trim();
  unsure = [...new Set((o.unclear_words || []).map((w) => String(w).trim()).filter((w) => w && text.includes(w)))];
} catch (e) {
  text = cand.a || cand.b || cand.c || '';
  ear = cand.a ? 'gpt-4o-transcribe' : cand.b ? 'gpt-transcribe' : 'whisper-large-v3';
}
const unsureNote = unsure.length ? '\n(كلمات بالصوت مو واضحة: ' + unsure.map((w) => '«' + w + '»').join('، ') + ')' : '';
return [{ json: { ear, text, confident: text.length > 0, unsureWords: unsure, unsureNote, candidates: { a: cand.a, b: cand.b, c: cand.c } }, pairedItem: 0 }];

// Voice messages: transcription can mishear names and short words, so the agent reads the order details back
// and asks before treating them as confirmed (Voice Confirm Guard enforces it on the reply)
const j = $json;
const msg = String(j.combinedMessage || '');
const hasVoice = /\[رسالة صوتية/.test(msg);
const unsure = [...msg.matchAll(/\(كلمات بالصوت مو واضحة: ([^)\n]*)\)/g)].map((m) => m[1]).join('، ');
let hint = '';
if (hasVoice) {
  hint = '\n\n[تنبيه: تأكيد الرسالة الصوتية — التفريغ الصوتي ممكن يغلط، خصوصاً بالأسماء. أي معلومة طلب جديدة أو معدّلة جت بهالرسالة الصوتية (الاسم، المنطقة، الشارع، أقرب نقطة دالة، الرقم، العدد والقياس واللون) '
    + 'أعدها على الزبون مثل ما فهمتها بصيغة تأكيد الطلب، وبنفس الرد اسأله «تمام هيج؟» (ممنوع «صحيح هالشي؟» و«صح هالمعلومات؟»). المعلومات الي قريتها عليه برد سابق لا تعيدها. لا تحط ✅ ولا تكتب «وصلني» كأنها مؤكدة قبل ما يأكدها. '
    + 'الاسم بالذات: اكتبه مثل ما فهمته واطلب منه يأكده، وإذا بيه غلط يكتبه كتابة.'
    + (unsure ? ' كلمات الصوت بيها مو واضح: ' + unsure + ' — اسأل عنها بالذات بسؤال واضح (قسم «رسالة مو مفهومة»): لا تعيد معلومات سابقة، ولا تبدي بـ «وصلني»، ولا تختم السؤال بـ «تمام هيج؟».' : '')
    + ' إذا كملت معلومات الطلب، الملخص نفسه يكون هو التأكيد: اكتب قبله سطر واحد قصير إن الاسم والعنوان وصلت بالصوت وخلي يتأكد منها، بدون قائمة ثانية للاسم والعنوان قبل الملخص.]';
}
return { json: { ...j, userPrompt: String(j.userPrompt || '') + hint, hasVoice } };

// Info heard from a voice message is never accepted silently: drop "accepted" ticks and make sure the reply asks.
// A reply that asks what the customer meant (a message or voice note that was not understood) asks only that:
// «وصلني …» sentences repeating details the customer already read in a recent reply go, and no «تمام هيج؟» is
// tacked onto the question.
const voice = (() => { try { return $('Voice Check').first().json.hasVoice === true; } catch (e) { return false; } })();
const ran = (node) => { try { return $(node).isExecuted === true; } catch (e) { return false; } };
const sentText = (() => { try { return String($('Repeat Hints').first().json.repeat.sentText || ''); } catch (e) { return ''; } })();
let text = String($json.output ?? '');

const CLARIFY = /شنو\s+(?:تقصد|تقصدين|قصدك|قصدچ|يعني)|ما\s+(?:فهمت|وضح|وضحت|انفهم|انفهمت)|مو\s+(?:واضح|واضحه|واضحة|مفهوم|مفهومه|مفهومة)/;
const norm = (s) => String(s).replace(/\p{M}/gu, '').replace(/[أإآٱ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه')
  .replace(/[٠-٩]/g, (d) => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d))).replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const clarifyOnly = (visible) => {
  const seen = new Set(norm(sentText).split(' ').filter(Boolean));
  let out = visible.split(/(?<=[.!؟?\n])/).filter((part) => {
    const s = part.trim();
    if (!/^(?:تمام[،,]?\s*)?وصل(?:ني|تني|نا)(?=[\s،,:]|$)/.test(s)) return true;
    const words = norm(s).split(' ').filter((w) => w.length >= 2 && !/^وصل/.test(w));
    return words.length > 0 && words.filter((w) => seen.has(w)).length / words.length < 0.7;
  }).join('');
  out = out.replace(/([؟?])[ \t]*تمام\s+(?:هيج|هيچ)\s*[؟?]/g, '$1');
  if ((out.replace(/تمام\s+(?:هيج|هيچ)\s*[؟?]/g, '').match(/[؟?]/g) || []).length) {
    out = out.replace(/\n[ \t]*تمام\s+(?:هيج|هيچ)\s*[؟?][ \t]*(?=\n|$)/g, '');
  }
  out = out.replace(/^\s*بس\s+/, '').replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  return out || visible;
};

// A reply that hands the chat to staff (NOTIFICATION_TYPE: complaint) goes out as it is: no confirmation question
const handoff = /NOTIFICATION_TYPE:\s*complaint/i.test(text);
if (!handoff && !ran('create_order') && (voice || CLARIFY.test(text))) {
  // Hidden STAGE / NOTIFICATION lines stay last; the question goes before them
  const lines = text.split('\n');
  const hidden = [];
  while (lines.length && /^(?:STAGE|NOTIFICATION_TYPE)\s*:/i.test(lines[lines.length - 1].trim())) hidden.unshift(lines.pop());
  let visible = lines.join('\n').trimEnd();
  if (CLARIFY.test(visible)) visible = clarifyOnly(visible);
  // A voice note at stage 0/1 (greeting, products, prices, «توصلون للعامرية؟») carries no order detail to
  // confirm: the answer naming what was heard is enough, and a tacked-on question was never asked for
  const stage = Number((hidden.join('\n').match(/STAGE:\s*(\d+)/i) || [])[1] ?? -1);
  if (voice && stage !== 0 && stage !== 1) {
    visible = visible.replace(/[ \t]*✅/g, '');
    // The full sentence once; a customer who already read it in a recent reply gets the short question
    const ASK = 'تمام هيج؟ إذا اكو شي مو مضبوط (خصوصاً الاسم) اكتبه كتابة.';
    if (!/[؟?]/.test(visible)) visible += '\n\n' + (sentText.includes(ASK) ? 'تمام هيج؟' : ASK);
  }
  text = visible + (hidden.length ? '\n' + hidden.join('\n') : '');
}
return { json: { ...$json, output: text } };

// What the bot already sent this customer (its last replies, 24 hours): tells the agent not to resend the color/size
// list or read the customer's details back again, and hands the same facts to Drop Repeated Blocks, which enforces it.
const j = $json;
const replies = (() => {
  try {
    let r = $('Load Recent Bot Replies').first().json.replies;
    if (typeof r === 'string') r = JSON.parse(r);
    return Array.isArray(r) ? r.map((x) => String(x || '')) : [];
  } catch (e) { return []; }
})();

const isMeta = (l) => /^(?:STAGE|NOTIFICATION_TYPE)\s*:/i.test(l.trim());
const BULLET = /^\s*(?:[-•▪●]|\d+\s*[.)-]|[٠-٩]+\s*[.)-])\s*/;
const plain = (l) => String(l).replace(BULLET, '').replace(/[*_]/g, '').replace(/\p{M}/gu, '')
  .replace(/[أإآٱ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه').trim();
const normLine = (l) => plain(l).replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
// «- الشارع: …», «الاسم: …»: a read-back of the customer's details
const READBACK = /^(?:ال)?(?:اسم[كچ]?|اسم الثلاثي|محافظه|منطقه|عنوان|شارع|حي|محله|زقاق|دار|اقرب نقطه داله|نقطه داله|رقم (?:ال)?(?:تواصل|هاتف|تلفون|موبايل)|لون|قياس|عدد)\s*[:：]/;
const isReadback = (l) => READBACK.test(plain(l));
// «- أسود: سمول، ميديم»، «- تيشيرت أبيض لارج»: the availability list (cart and summary lines carry ×, = or قطع)
const SIZE = /سمول|ميديم|لارج|small|medium|large|(?<![a-z])xl(?![a-z])/i;
const isList = (l) => (BULLET.test(l) || /^[^:：]{1,30}[:：]/.test(plain(l))) && !isReadback(l)
  && SIZE.test(plain(l)) && !/[×=]|قطع|المجموع|الكلي/.test(plain(l));

const lines = replies.flatMap((r) => r.split('\n')).filter((l) => l.trim() && !isMeta(l));
const sentLines = [...new Set(lines.map(normLine).filter(Boolean))];
// The newest full order summary the customer saw (bullets and «label: value» lines), for Drop Repeated Blocks
const CONFIRM_Q = /[أا]ثب\p{M}*ت\p{M}*(?:\s?(?:لك|لچ|لج))?\s+(?:الطلب|طلبك|طلبچ)\s*[؟?]/u;
const isInfo = (l) => l.trim() && !isMeta(l) && !CONFIRM_Q.test(l) && (BULLET.test(l) || /^[^:：]{1,30}[:：]\s*\S/.test(plain(l)));
const lastSummary = replies.filter((r) => CONFIRM_Q.test(r))
  .map((r) => [...new Set(r.split('\n').filter(isInfo).map(normLine).filter(Boolean))])
  .find((ls) => ls.length >= 2) || [];
const sentList = lines.some(isList);
const sentReadback = replies.some((r) => r.split('\n').filter(isReadback).length >= 2 && !/ملخص|المجموع/.test(r));

// The customer asks about products (colors, sizes, prices, availability) or asks to hear something again:
// then nothing is held back this turn
const msg = ' ' + normLine(String(j.combinedMessage || '').replace(/\[[^\]\n]*\]:?/g, ' ')).toLowerCase() + ' ';
const colorWords = new Set(lines.filter(isList)
  .flatMap((l) => normLine(plain(l).split(/[:：]/)[0]).split(' '))
  .filter((w) => w.length >= 3 && !SIZE.test(w) && !/^(?:تيشيرت|تيشيرتات|تشيرت|اكس|دينار)$/.test(w)));
const AT = '(?:^| )(?:[وبلف]|وب)?(?:ال)?';
const PRODUCT = new RegExp(AT + '(?:لون|الوان|قياس|قياسات|مقاس|مقاسات|سمول|ميديم|لارج|اكس|سعر|سعره|سعرها|اسعار|متوفر|متوفره|عدكم|عندكم|عدك|عندك|تيشيرت|تيشيرتات|تشيرت|تشيرتات|منتجات|small|medium|large|xl'
  + '|اسود|سودا|سوده|ابيض|بيضا|بيضه|احمر|حمرا|حمره|ازرق|زرقا|زرقه|اخضر|خضرا|خضره|اصفر|صفرا|صفره|رمادي|رصاصي|بيجي|وردي|زهري|بني|نيلي|كحلي|جوزي|برتقالي|بنفسجي|سماوي|فضي|ذهبي|عنابي|زيتي|خاكي|ماروني)(?:ات)?(?= |$)');
const askedList = PRODUCT.test(msg) || [...colorWords].some((w) => new RegExp(AT + w + '(?= |$)').test(msg));
const askedRepeat = new RegExp(AT + '(?:ا?عيد|اعيد|عيدلي|عيدها|عيديها|كرر|كررها|ذكرني)(?= |$)').test(msg)
  || / (?:ما فهمت|ما وصل|ما وصلني|ما وصلت|شنو قلت|شنو سجلت|شنو كتبت|الملخص|ملخص) /.test(msg);

let hint = '';
if (replies.length && !askedRepeat) {
  hint += '\n\n[تنبيه: لا تعيد نفس الرسالة — الزبون قرا ردودك السابقة. جاوب على رسالته الأخيرة بس، ولا تنسخ ردك السابق ولا تبدي بنفس الجملة.';
  if (sentList && !askedList) hint += ' قائمة الألوان والقياسات انرسلت قبل، فلا تعيدها، ولا تسأله عن اللون أو القياس إلا إذا قال إنه رايد يطلب.';
  if (sentReadback) hint += ' قريت عليه معلوماته (الاسم والعنوان) قبل، فلا تعيدها كلها؛ أكّد بس المعلومة الجديدة أو المعدّلة بهالرسالة، مثل: «الشارع: شارع جامع الحسنين، تمام؟».';
