const clip = (s, n) => {
  const t = String(s ?? '').replace(/\s+/g, ' ').trim();
  return t.length > n ? t.slice(0, n) + '…' : t;
};
const bare = (s) => String(s ?? '').replace(/\p{M}/gu, '');
const rows = (name) => { try { return $(name).all().map((i) => i.json || {}); } catch (e) { return []; } };

// Context: earlier customer messages (24h), the bot's last replies, the order being placed, an earlier order on record
const earlier = rows('Load Recent Customer Messages')
  .filter((r) => r.message_text)
  .slice(0, 6)
  .reverse()
  .map((r) => '- ' + clip(r.message_text, 200));
const botReplies = (() => {
  const r = rows('Load Recent Bot Replies')[0];
  let a = r && r.replies;
  if (typeof a === 'string') { try { a = JSON.parse(a); } catch (e) { a = []; } }
  return Array.isArray(a) ? a.filter(Boolean) : [];
})();
const lastBotReply = String(botReplies[0] || '');
const olderBot = botReplies.slice(1, 3).reverse().map((t) => '- ' + clip(t, 300));
const cart = base.sessionData && Array.isArray(base.sessionData.cart) ? base.sessionData.cart : [];
const cartText = cart.length
  ? cart.map((c) => [c.quantity, c.color, c.size].filter((v) => v !== undefined && v !== null && v !== '').join(' ')).join('، ')
  : 'nothing saved';
const prev = rows('Load Previous Address').find((r) => r.order_id) || {};
const prevText = prev.order_id ? `yes, order #${prev.order_id} placed ${String(prev.created_at || '').slice(0, 10)}` : 'none found';

// Is the bot in the middle of taking an order? Its last reply read the order back, asked for the quantity, colour,
// size or address, offered to add or confirm, or listed what is in stock, and no order number has been given yet.
// (Plain mentions of sizes, delivery or the exchange policy do not count, nor the voice-note check «تمام هيج؟ إذا اكو شي مو مضبوط».)
const lastBare = bare(lastBotReply);
const ORDER_CUES = /طلب[كچ] (?:هس[ةه] )?صار|تفاصيل طلب[كچ]|شكم (?:قطعة|قطع)|تحب تضيف|تضيفه|ملخص طلب|[أا]ثبتل[كچج] (?:الطلب|ياه)|عنوان[كچ] الكامل|[أا]قرب نقطة دالة|شنو (?:اللون|القياس|العدد)|(?:اللون|القياس|العدد) الي رايد/;
const STOCK_CUES = /متوفر|ماكو حالي/;
const ITEM_WORDS = /قطع|حب[ةه]|حبات|قياس|لون|موديل|كمية|تيشيرت|سمول|ميديم|لارج|اكس|XL/i;
const ORDER_DONE = /رقم\s*(?:الطلب\s*)?[#:]?\s*#?\s*[0-9٠-٩]+|المندوب يتصل|تم تثبيت/;
const orderingNow = (ORDER_CUES.test(lastBare) || (STOCK_CUES.test(lastBare) && ITEM_WORDS.test(lastBare))) && !ORDER_DONE.test(lastBare);
// Words that point at an order already placed or delivered (received, arrived, the courier, washed or wore it,
// last time, yesterday, a week ago…)
const DELIVERY_WORDS = new RegExp('(^|[^ء-ي])[وف]?[بل]?(?:' + [
  'وصل(?:ني|تني|ت|ته|تها|ه|ها|و|وا|نا|لي|ولي|تلي)?', 'واصل[ء-ي]*', 'استلم[ء-ي]*',
  'جا(?:ني|تني|نا|بولي|بلي|به|بوه|بوها)', '[اإ]جا(?:ني|تني|نا)', '[اإ]جتني', 'رجع(?:وه|ته|تها|وا|وها)?',
  'المندوب', 'مندوب', 'الدلفري', 'دلفري', 'الديلفري',
  'السابق[ةه]?', 'الماضي[ةه]?', 'الفات[تة]?', 'الفايت[ةه]?', '[اآ]خر طلب',
  'قبل (?:[0-9٠-٩]+ )?(?:يوم|يومين|ايام|أيام|اسبوع|أسبوع|اسبوعين|أسبوعين|شهر|فترة)',
  'غسلت[ء-ي]*', 'لبست[ء-ي]*', 'انكمش[ء-ي]*', 'البارح[ةه]', '[اأ]مس',
].join('|') + ')(?![ء-ي])');
const mentionsDelivery = DELIVERY_WORDS.test(bare(base.combinedMessage));

const SYSTEM = `You check one turn of a customer chat for an online shop that sells through WhatsApp, Messenger and Instagram, usually with cash on delivery. Customers write in Iraqi Arabic, often with typos. Some messages are voice-note transcripts ("[رسالة صوتية]: …") or labels such as "[صورة مرسلة]".

Decide whether the NEW customer messages contain a complaint that a staff member must handle, or a request to talk to a person. When you say yes, the bot stops and a human takes over the chat, so be accurate both ways: a missed complaint leaves an upset customer with a bot, and a false alarm stops a customer in the middle of buying.

First look at the chat state given in the context. When the bot is in the middle of taking an order (its last reply offered items, listed what is in stock, repeated the order back, or asked for size, colour, quantity, name or address), messages such as "غلط", "مو هذا", "مو الي طلبته", "ما فهمتني", "اريد ميديم مو لارج" correct the order being placed now. They are NOT complaints unless the customer clearly talks about something already delivered or received (وصلني، استلمت، جاني، المندوب) or about an earlier order.

It IS a complaint (is_complaint = true) when the customer reports a problem with an order they already placed or received, or with the shop's service. This holds even when it is said calmly, without the word "شكوى" and without anger:
- wrong_item: the size, colour, model, design or quantity they got is not what they ordered ("وصلني الطلب بس القياس غلط", "اللون مو نفس الي طلبته", "جاني أبيض وآني طالب أسود"). When no order is being taken in the chat right now and the customer says the size or colour is wrong or "مو نفس الي طلبته", it is about an order they received, even without the word "وصلني".
- damaged_or_defective: torn, stained, faded or cracked print, bad stitching or quality, shrank or lost colour after washing, not like the photo
- missing_items: fewer pieces than ordered, an item missing from the parcel
- late_or_not_delivered: the order is late, has not arrived when it should have, or the courier never came
- courier_problem: the courier was rude, asked for more money, did not call, or did not deliver to the address
- billing_problem: charged more than agreed, a wrong total or wrong change
- bad_service: unhappy with how they were treated, acted on wrong information from the shop, or an order was cancelled without telling them
- wants_human: asks for a person, staff, the owner or management, or says they do not want to talk to a bot ("أريد أحچي ويا موظف", "حولني على الإدارة", "ما أريد روبوت")
- other_complaint: any other clear problem with an order or the shop that needs a person

It is NOT a complaint (is_complaint = false, category "none"):
- correcting or changing the order being placed now, or correcting what the bot understood ("لا غلط، اريد ميديم مو لارج", "اللون غلط اريدهم أسود", "هذا مو الي طلبته، آني كلت ميديم", "ما فهمتني اريد أبيض") while the bot is taking an order
- answering the bot's question (name, address, phone number, size, quantity)
- questions before or after buying: prices, sizes, colours, stock, delivery fee or time, payment, or the exchange and return policy asked in advance ("إذا القياس ما ضبط تبدلوه؟", "متى يوصل طلبي؟" when nothing says it is late)
- an item being out of stock, the price being high, or asking for a discount ("غالي", "نزلي شوية")
- praise or thanks after delivery ("وصلني الطلب حلو كلش"), greetings, small talk
- a bad experience with another shop
- cancelling or changing an order without reporting a problem

Judge only the NEW customer messages and use the context only to understand them. If the new messages mix a real complaint with other questions, it is a complaint.

about_earlier_order: true when the new messages are about an order placed before this chat's current ordering steps (already delivered, on the way, late, returned or cancelled); false when they are about the order being put together now, or about no order at all.

confidence: high = clearly a complaint or a clear request for a person; medium = most likely a complaint, but a detail is unclear; low = probably not, only a hint of dissatisfaction.

Fill reason first with one short English sentence on what the customer is saying, then the other fields. evidence holds the customer's own words that show the complaint (empty when there is none).`;

const SCHEMA = {
  type: 'object',
  properties: {
    reason: { type: 'string' },
    about_earlier_order: { type: 'boolean' },
    evidence: { type: 'string' },
    category: {
      type: 'string',
      enum: ['wrong_item', 'damaged_or_defective', 'missing_items', 'late_or_not_delivered', 'courier_problem',
        'billing_problem', 'bad_service', 'wants_human', 'other_complaint', 'none'],
    },
    is_complaint: { type: 'boolean' },
    confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
  },
  required: ['reason', 'about_earlier_order', 'evidence', 'category', 'is_complaint', 'confidence'],
  additionalProperties: false,
};

const context = [
  'Chat state: ' + (orderingNow
    ? 'the bot is in the middle of taking an order (its last reply offered items, listed stock, repeated the order back or asked for order details).'
    : lastBotReply ? 'no order is being taken right now.' : 'this is the start of the chat.'),
  '',
  'Earlier customer messages (last 24 hours, oldest first):',
  earlier.length ? earlier.join('\n') : '- none',
  '',
  "The bot's earlier replies (oldest first):",
  olderBot.length ? olderBot.join('\n') : '- none',
  '',
  "The bot's most recent reply (just before the new messages):",
  lastBotReply ? '- ' + clip(lastBotReply, 500) : '- none',
  '',
  'Items saved for the order being placed now: ' + cartText,
  'Earlier order on record for this customer: ' + prevText,
].join('\n');

const complaintRequest = {
  model: 'gpt-4o-mini',
  temperature: 0,
  max_tokens: 220,
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user', content: 'CONTEXT\n' + context + '\n\nNEW CUSTOMER MESSAGES (classify these)\n' + clip(base.combinedMessage, 1500) },
  ],
  response_format: { type: 'json_schema', json_schema: { name: 'complaint_check', strict: true, schema: SCHEMA } },
};

return [{ json: { ...item, complaintRequest, complaintContext: { orderingNow, mentionsDelivery } }, pairedItem: { item: 0 } }];

// Complaint check, step 3 of 3 (before the agent): read the classifier's answer. On a complaint (medium or high
// confidence) tell the agent to follow its complaint section; the decision travels on as complaintCheck so that
// Complaint Guard can hand the chat to staff even if the agent does not. While the bot is taking an order, a
// "wrong size / colour / count / price" message counts only when the customer points at something already
// delivered or received. If the classifier call failed, nothing changes and the agent decides alone, as before.
const item = $('Build Complaint Check').first().json;
const ctx = item.complaintContext || {};
const res = $input.first().json || {};
let answer = null;
try {
  const content = res.choices[0].message.content;
  answer = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  answer = null;
}
const CATEGORIES = ['wrong_item', 'damaged_or_defective', 'missing_items', 'late_or_not_delivered', 'courier_problem',
  'billing_problem', 'bad_service', 'wants_human', 'other_complaint'];
// Problems that, while the bot is taking an order, usually mean "fix my order" rather than a complaint
// («اللون غلط، اريدهم أسود», «العدد غلط»). Torn or late orders, the courier, bad service and asking for a person
// are never held back.
const CORRECTABLE = ['wrong_item', 'missing_items', 'billing_problem'];
const ok = !!answer && typeof answer.is_complaint === 'boolean';
let handoff = ok && answer.is_complaint === true && CATEGORIES.includes(answer.category) && answer.confidence !== 'low';
let heldBack = '';
// (about_earlier_order is reported for review only: in testing it was often false for clear complaints about a
// delivered order, so it does not decide anything.)
if (handoff && CORRECTABLE.includes(answer.category) && ctx.orderingNow === true && ctx.mentionsDelivery !== true) {
  handoff = false;
  heldBack = 'the bot is taking an order and the customer mentions nothing delivered or received, so it reads as a correction';
}
const errorText = (() => {
  if (ok) return '';
  const e = res.error;
  if (e) return String(e.message || e.description || (typeof e === 'string' ? e : JSON.stringify(e))).slice(0, 300);
  return 'no usable classifier answer';
})();

const complaintCheck = {
  ok,
  handoff,
  heldBack,
  is_complaint: ok ? answer.is_complaint : null,
  category: ok ? answer.category : null,
  confidence: ok ? answer.confidence : null,
  about_earlier_order: ok ? answer.about_earlier_order : null,
  ordering_now: ctx.orderingNow === true,
  mentions_delivery: ctx.mentionsDelivery === true,
  evidence: ok ? String(answer.evidence || '') : '',
  reason: ok ? String(answer.reason || '') : '',
  error: errorText,
};

const LABELS = {
  wrong_item: 'طلب واصل غلط (قياس أو لون أو عدد)',
  damaged_or_defective: 'قطعة بيها عيب أو تلف',
  missing_items: 'قطع ناقصة من الطلب',
  late_or_not_delivered: 'تأخير أو الطلب ما وصل',
  courier_problem: 'مشكلة ويا المندوب',
  billing_problem: 'مشكلة بالمبلغ',
  bad_service: 'زعل من الخدمة',
  other_complaint: 'شكوى',
};
let userPrompt = String(item.userPrompt || '');
// The customer gets Complaint Guard's fixed handoff message either way; the hint keeps the agent (and its memory)
// in line with that message. No store name here: the same node serves every merchant.
if (handoff) {
  userPrompt += answer.category === 'wants_human'
    ? '\n\n[تنبيه داخلي من فحص الشكاوى: الزبون يريد يحچي ويا موظف. بلّغه بجملة قصيرة إن المحادثة تحوّلت لموظف الدعم'
      + ' وراح يرد عليه بأقرب وقت، بدون أسئلة، وأنهِ الرد بسطر NOTIFICATION_TYPE: complaint]'
    : '\n\n[تنبيه داخلي من فحص الشكاوى: رسالة الزبون شكوى (' + LABELS[answer.category] + '). رد باعتذار قصير وصادق، وبلّغه إن الموضوع'
      + ' تحوّل لموظف الدعم وراح يتابعه وياه بأقرب وقت، بدون أسئلة وبدون وعود، وأنهِ الرد بسطر NOTIFICATION_TYPE: complaint]';
}

const { complaintRequest, complaintContext, ...rest } = item;
return [{ json: { ...rest, userPrompt, complaintCheck }, pairedItem: { item: 0 } }];

// Complaint check, after the agent: the handoff no longer depends on the agent alone. When the classifier found a
// complaint or the agent flagged one, the customer gets one fixed handoff message instead of the agent's own wording
// (kept in complaintDecision.agentReply for staff), and the reply carries NOTIFICATION_TYPE: complaint, so
// Is Complaint? hands the chat to staff. The messages name no store, so the same node serves every merchant.
const HANDOFF = {
  complaint: 'حقك علينا، وآسفين على هالإزعاج 🙏 الموضوع تحوّل لموظف الدعم، وراح يتابعه وياك بأقرب وقت.',
  wants_human: 'تدلل، المحادثة تحوّلت لموظف الدعم، وراح يرد عليك بأقرب وقت.',
};
const check = (() => { try { return $('Complaint Hint').first().json.complaintCheck || {}; } catch (e) { return {}; } })();
const raw = String($json.output ?? $json.text ?? '');
const agentFlag = /NOTIFICATION_TYPE:\s*complaint/i.test(raw);
const classifierFlag = check.handoff === true;
const handoff = agentFlag || classifierFlag;
let text = raw;
if (handoff) {
  text = (classifierFlag && check.category === 'wants_human' ? HANDOFF.wants_human : HANDOFF.complaint)
    + '\nSTAGE: 5\nNOTIFICATION_TYPE: complaint';
}

const complaintDecision = {
  handoff,
  source: agentFlag && classifierFlag ? 'both' : agentFlag ? 'agent' : classifierFlag ? 'classifier' : 'none',
  replyReplaced: handoff,
  classifier: {
    ok: check.ok === true,
    is_complaint: check.is_complaint ?? null,
    category: check.category ?? null,
    confidence: check.confidence ?? null,
    about_earlier_order: check.about_earlier_order ?? null,
    ordering_now: check.ordering_now === true,
    mentions_delivery: check.mentions_delivery === true,
    heldBack: check.heldBack || '',
    evidence: check.evidence || '',
    reason: check.reason || '',
    error: check.error || '',
  },
};
if (handoff) complaintDecision.agentReply = raw;

return { json: { ...$json, output: text, complaintDecision } };

const MAX_LENGTH = 4000;
const BLOCK_THRESHOLD = 50;
const ARABIC_DIACRITICS = /[ً-ٰٟـ]/g;
const ZERO_WIDTH = /[​-‏‪-‮⁠-⁤﻿]/g;
function normalize(input) {
    return input
        .normalize("NFKC")
        .replace(ZERO_WIDTH, "")
        .replace(ARABIC_DIACRITICS, "")
        .replace(/[إأآا]/g, "ا")
        .replace(/ى/g, "ي")
        .replace(/ة/g, "ه")
        .replace(/[٠-٩]/g, (d) => String(d.charCodeAt(0) - 0x0660))
        .replace(/[۰-۹]/g, (d) => String(d.charCodeAt(0) - 0x06f0))
        .replace(/٪/g, "%")
        .toLowerCase()
        .replace(/\s+/g, " ")
        .trim();
}
const SIGNATURES = [
    { category: "INSTRUCTION_OVERRIDE", weight: 60, pattern: /\b(ignore|disregard|forget|override|bypass|skip)\b.{0,30}\b(previous|prior|above|all|earlier|system|your)\b.{0,20}\b(instructions?|rules?|prompts?|guidelines?|polic(y|ies))\b/ },
    { category: "INSTRUCTION_OVERRIDE", weight: 60, pattern: /(?:^|[^ء-ي])[وف]?(تجاهل|انس|الغ|اهمل|تخط|تجاوز|لا تلتزم ب?)(?:ي|وا)?(?![ء-ي]).{0,25}(التعليمات|القواعد|الاوامر|التوجيهات|السياسات|النظام)/ },
    { category: "INSTRUCTION_OVERRIDE", weight: 45, pattern: /\b(new|updated) (instructions?|rules?)\b|من الان (فصاعدا )?(انت|ستكون|يجب)/ },
    { category: "PRICE_MANIPULATION", weight: 55, pattern: /\b(set|change|make|update|lower|reduce)\b.{0,25}\b(price|cost|total|amount|fee)\b.{0,25}(\bto\b|=)\s*(\$?\s*0|zero|free|\d+)/ },
    { category: "PRICE_MANIPULATION", weight: 55, pattern: /(?:^|[^ء-ي])[وف]?(غير|اجعل|عدل|خفض|حدد|ضع)(?:ي|وا|و)?(?![ء-ي]).{0,20}(السعر|الثمن|التكلفه|المبلغ|الاجمالي|الرسوم).{0,25}(الي|ل|=|يساوي|بـ?)\s*(0|صفر|مجان|\d+)/ },
    { category: "PRICE_MANIPULATION", weight: 50, pattern: /\b100\s*% (discount|off)\b|\bfull discount\b|خصم\s*(100\s*(%|بالمئه|في المئه)|كامل|مئه بالمئه)/ },
    { category: "PRICE_MANIPULATION", weight: 40, pattern: /\b(apply|give|grant)\b.{0,20}\b(discount|coupon|refund)\b.{0,20}\b(without|no) (code|approval|verification)\b/ },
    { category: "ROLE_HIJACK", weight: 50, pattern: /\b(you are now|act as|pretend (to be|you are)|roleplay as|from now on you)\b|\b(dan mode|do anything now|developer mode|jailbreak|god mode)\b/ },
    { category: "ROLE_HIJACK", weight: 50, pattern: /(انت الان|تصرف ك|تظاهر بانك|العب دور|وضع المطور|بصفتك مدير|انا المدير|انا المطور)/ },
    { category: "SYSTEM_PROMPT_LEAK", weight: 55, pattern: /\b(reveal|show|print|repeat|output|tell me)\b.{0,25}\b(system prompt|initial instructions|hidden (rules|prompt)|your instructions)\b/ },
    { category: "SYSTEM_PROMPT_LEAK", weight: 55, pattern: /(اظهر|اعرض|اطبع|كرر|اكشف|ما هي).{0,20}(تعليماتك|البرومبت|موجه النظام|القواعد المخفيه|تعليمات النظام)/ },
    { category: "INSTRUCTION_OVERRIDE", weight: 50, pattern: /(<\|?(im_start|im_end|system|endoftext)\|?>|\[\/?(inst|system)\]|###\s*(system|instruction)|^\s*system\s*:)/m },
    { category: "CODE_INJECTION", weight: 60, pattern: /<\s*(script|iframe|object|embed|svg)[^>]*>|javascript\s*:|\bon(error|load|click)\s*=/ },
    { category: "CODE_INJECTION", weight: 60, pattern: /\b(union\s+select|drop\s+table|insert\s+into|delete\s+from|update\s+\w+\s+set)\b|('|")\s*(or|and)\s+\d+\s*=\s*\d+|;\s*--/ },
    { category: "CODE_INJECTION", weight: 55, pattern: /\b(eval|exec|new function|child_process|require\s*\(|import\s*\(|process\.env|__proto__|constructor\.prototype)\b/ },
    { category: "CODE_INJECTION", weight: 50, pattern: /(\$\(|`[^`]*`|\$\{[^}]*\}|\{\{[^}]*\}\}|;\s*(rm|curl|wget|bash|sh)\b|&&\s*(rm|curl|wget)\b)/ },
    { category: "OBFUSCATION", weight: 30, pattern: /\b(base64|rot13|hex)\b.{0,20}\b(decode|decrypt)\b|فك (التشفير|الترميز)/ },
    { category: "OBFUSCATION", weight: 25, pattern: /[A-Za-z0-9+/]{60,}={0,2}/ },
];
const LEXICON = {
    modifyVerbs: ["change", "modify", "set", "update", "override", "alter", "lower", "reduce", "make it", "غير", "عدل", "اجعل", "حدث", "خفض", "بدل", "ضع"],
    negateVerbs: ["ignore", "forget", "disregard", "bypass", "skip", "don't follow", "تجاهل", "انس", "اهمل", "تجاوز", "الغ", "لا تتبع"],
    priceTargets: ["price", "cost", "total", "fee", "discount", "invoice", "payment", "free", "السعر", "الثمن", "التكلفه", "الفاتوره", "المبلغ", "الاجمالي", "الدفع", "خصم", "مجانا", "مجاني", "رسوم"],
    ruleTargets: ["rules", "instructions", "policy", "system", "prompt", "guidelines", "restrictions", "القواعد", "التعليمات", "السياسه", "النظام", "القيود", "الاوامر"],
    authorityClaims: ["i am the admin", "i'm the admin", "as an admin", "i am the developer", "authorized", "official request", "انا المدير", "انا الادمن", "انا المطور", "مصرح لي", "طلب رسمي", "بامر من الاداره"],
    urgency: ["immediately", "urgent", "right now", "must", "فورا", "حالا", "ضروري", "يجب عليك"],
};
const WORD_CHAR = "[a-z0-9ء-ي]";
const AR_PREFIX = "(?:و|ف|ب|ل|ك|ال|وال|بال|فال|لل)?";
const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const matcherCache = new Map();
function hasWord(text, word) {
    let re = matcherCache.get(word);
    if (!re) {
        re = new RegExp(`(?:^|[^a-z0-9ء-ي])${AR_PREFIX}${escapeRe(word)}(?!${WORD_CHAR})`);
        matcherCache.set(word, re);
    }
    return re.test(text);
}
const countHits = (text, words) => words.reduce((n, w) => (hasWord(text, w) ? n + 1 : n), 0);
function semanticScore(text) {
    const modify = countHits(text, LEXICON.modifyVerbs);
