        categories.push("PRICE_MANIPULATION");
    }
    if (negate && rules) {
        score += 35 + Math.min(rules, 3) * 5;
        categories.push("INSTRUCTION_OVERRIDE");
    }
    if (authority) {
        score += 20 * Math.min(authority, 2);
        categories.push("ROLE_HIJACK");
